CREATE TABLE `Ref_Hotel_Star_Ratings` (
  `star_rating_code` TEXT,
  `star_rating_description` TEXT,
  PRIMARY KEY (`star_rating_code`)
);

CREATE TABLE `Locations` (
  `Location_ID` NUMBER,
  `Location_Name` TEXT,
  `Address` TEXT,
  `Other_Details` TEXT,
  PRIMARY KEY (`Location_ID`)
);

