  `Tourist_ID` NUMBER,
  `Tourist_Details` TEXT,
  PRIMARY KEY (`Tourist_ID`)
);

CREATE TABLE `Features` (
  `Feature_ID` NUMBER,
  `Feature_Details` TEXT,
  PRIMARY KEY (`Feature_ID`)
);

