  `Market_ID` NUMBER REFERENCES `Tourist_Attractions`(`Tourist_Attraction_ID`),
  `Market_Details` TEXT,
  PRIMARY KEY (`Market_ID`)
);

CREATE TABLE `Shops` (
  `Shop_ID` NUMBER REFERENCES `Tourist_Attractions`(`Tourist_Attraction_ID`),
  `Shop_Details` TEXT,
  PRIMARY KEY (`Shop_ID`)
);

CREATE TABLE `Museums` (
  `Museum_ID` NUMBER REFERENCES `Tourist_Attractions`(`Tourist_Attraction_ID`),
  `Museum_Details` TEXT,
  PRIMARY KEY (`Museum_ID`)
);

CREATE TABLE `Royal_Family` (
  `Royal_Family_ID` NUMBER REFERENCES `Tourist_Attractions`(`Tourist_Attraction_ID`),
  `Royal_Family_Details` TEXT,
  PRIMARY KEY (`Royal_Family_ID`)
);

CREATE TABLE `Theme_Parks` (
  `Theme_Park_ID` NUMBER REFERENCES `Tourist_Attractions`(`Tourist_Attraction_ID`),
  `Theme_Park_Details` TEXT,
  PRIMARY KEY (`Theme_Park_ID`)
);

CREATE TABLE `Visits` (
  `Visit_ID` NUMBER,
  `Tourist_Attraction_ID` NUMBER REFERENCES `Tourist_Attractions`(`Tourist_Attraction_ID`),
  `Tourist_ID` NUMBER REFERENCES `Visitors`(`Tourist_ID`),
  `Visit_Date` TIME,
  `Visit_Details` TEXT,
  PRIMARY KEY (`Visit_ID`)
);

CREATE TABLE `Photos` (
  `Photo_ID` NUMBER,
  `Tourist_Attraction_ID` NUMBER REFERENCES `Tourist_Attractions`(`Tourist_Attraction_ID`),
  `Name` TEXT,
  `Description` TEXT,
  `Filename` TEXT,
  `Other_Details` TEXT,
  PRIMARY KEY (`Photo_ID`)
);

CREATE TABLE `Staff` (
  `Staff_ID` NUMBER,
  `Tourist_Attraction_ID` NUMBER REFERENCES `Tourist_Attractions`(`Tourist_Attraction_ID`),
  `Name` TEXT,
  `Other_Details` TEXT,
  PRIMARY KEY (`Staff_ID`)
);

CREATE TABLE `Tourist_Attraction_Features` (
  `Tourist_Attraction_ID` NUMBER REFERENCES `Tourist_Attractions`(`Tourist_Attraction_ID`),
  `Feature_ID` NUMBER REFERENCES `Features`(`Feature_ID`),
  PRIMARY KEY (`Tourist_Attraction_ID`)
);

