  `aid` NUMBER,
  `homepage` TEXT,
  `name` TEXT,
  `oid` NUMBER,
  PRIMARY KEY (`aid`)
);

CREATE TABLE `conference` (
  `cid` NUMBER,
  `homepage` TEXT,
  `name` TEXT,
  PRIMARY KEY (`cid`)
);

CREATE TABLE `domain` (
  `did` NUMBER,
  `name` TEXT,
  PRIMARY KEY (`did`)
);

CREATE TABLE `domain_author` (
  `aid` NUMBER REFERENCES `author`(`aid`),
  `did` NUMBER REFERENCES `domain`(`did`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `domain_conference` (
  `cid` NUMBER REFERENCES `conference`(`cid`),
  `did` NUMBER REFERENCES `domain`(`did`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `journal` (
  `homepage` TEXT,
  `jid` NUMBER,
  `name` TEXT,
  PRIMARY KEY (`jid`)
);

CREATE TABLE `domain_journal` (
  `did` NUMBER REFERENCES `domain`(`did`),
  `jid` NUMBER REFERENCES `journal`(`jid`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `keyword` (
  `keyword` TEXT,
  `kid` NUMBER,
  PRIMARY KEY (`kid`)
);

CREATE TABLE `domain_keyword` (
  `did` NUMBER REFERENCES `domain`(`did`),
  `kid` NUMBER REFERENCES `keyword`(`kid`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `publication` (
  `abstract` TEXT,
  `cid` TEXT REFERENCES `conference`(`cid`),
  `citation_num` NUMBER,
  `jid` NUMBER REFERENCES `journal`(`jid`),
  `pid` NUMBER,
  `reference_num` NUMBER,
  `title` TEXT,
  `year` NUMBER,
  PRIMARY KEY (`pid`)
);

CREATE TABLE `domain_publication` (
  `did` NUMBER REFERENCES `domain`(`did`),
  `pid` NUMBER REFERENCES `publication`(`pid`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `organization` (
  `continent` TEXT,
  `homepage` TEXT,
  `name` TEXT,
  `oid` NUMBER,
  PRIMARY KEY (`oid`)
);

CREATE TABLE `publication_keyword` (
  `pid` NUMBER REFERENCES `publication`(`pid`),
  `kid` NUMBER REFERENCES `keyword`(`kid`),
  PRIMARY KEY (`kid`)
);

CREATE TABLE `writes` (
  `aid` NUMBER REFERENCES `author`(`aid`),
  `pid` NUMBER REFERENCES `publication`(`pid`),
  PRIMARY KEY (`aid`)
);

CREATE TABLE `cite` (
  `cited` NUMBER REFERENCES `publication`(`pid`),
  `citing` NUMBER REFERENCES `publication`(`pid`)
);

Question:
return me the number of papers written by " H. V. Jagadish " and " Divesh Srivastava " before 2000 .

Database Schema:
CREATE TABLE `alignment` (
  `id` INTEGER,
  `alignment` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `attribute` (
  `id` INTEGER,
  `attribute_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `colour` (
  `id` INTEGER,
  `colour` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `gender` (
  `id` INTEGER,
  `gender` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `publisher` (
  `id` INTEGER,
  `publisher_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `race` (
  `id` INTEGER,
  `race` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `superhero` (
  `id` INTEGER,
  `superhero_name` TEXT,
  `full_name` TEXT,
  `gender_id` INTEGER REFERENCES `gender`(`id`),
  `eye_colour_id` INTEGER REFERENCES `colour`(`id`),
  `hair_colour_id` INTEGER REFERENCES `colour`(`id`),
  `skin_colour_id` INTEGER REFERENCES `colour`(`id`),
  `race_id` INTEGER REFERENCES `race`(`id`),
  `publisher_id` INTEGER REFERENCES `publisher`(`id`),
  `alignment_id` INTEGER REFERENCES `alignment`(`id`),
  `height_cm` INTEGER,
  `weight_kg` INTEGER,
  PRIMARY KEY (`id`)
);

CREATE TABLE `hero_attribute` (
  `hero_id` INTEGER REFERENCES `superhero`(`id`),
  `attribute_id` INTEGER REFERENCES `attribute`(`id`),
  `attribute_value` INTEGER
);

CREATE TABLE `superpower` (
  `id` INTEGER,
  `power_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `hero_power` (
  `hero_id` INTEGER REFERENCES `superhero`(`id`),
  `power_id` INTEGER REFERENCES `superpower`(`id`)
);

Question:
Among the superheroes with the race of god/eternal, how many of them are male

Evidence:
race "god/eternal" refers to race_id = 21; male refers to gender.id = 1

